"""Canonical expression identities independent of the legacy monolith."""

from __future__ import annotations

import hashlib
import re
from typing import Any

from alpha_mining.common import sig
from .operator_registry import BASE_VARS, FUNCTIONS, GROUPS, LITERALS

_NUMBER = re.compile(r"(?<![a-z_])[-+]?\d+(?:\.\d+)?(?:e[-+]?\d+)?", re.I)


def extract_functions(expression: str) -> list[str]:
    return re.findall(r"\b([a-z_][a-z0-9_]*)\s*\(", str(expression or "").lower())


def extract_identifiers(expression: str) -> list[str]:
    return re.findall(r"\b[a-z_][a-z0-9_]*\b", str(expression or "").lower())


def extract_fields(expression: str) -> list[str]:
    excluded = FUNCTIONS | GROUPS | BASE_VARS | LITERALS
    return list(
        dict.fromkeys(
            token for token in extract_identifiers(expression) if token not in excluded
        )
    )


def exact_hash(expression: str) -> str:
    return hashlib.sha256(sig(expression).encode("utf-8")).hexdigest()


def normalized_expression(expression: str) -> str:
    text = sig(expression).lower()
    text = _NUMBER.sub("#", text)
    return re.sub(r"\s+", "", text)


def _strip_outer(text: str) -> str:
    text = text.strip()
    while text.startswith("(") and text.endswith(")"):
        depth = 0
        complete = True
        for index, char in enumerate(text):
            depth += 1 if char == "(" else -1 if char == ")" else 0
            if depth == 0 and index != len(text) - 1:
                complete = False
                break
        if not complete or depth:
            break
        text = text[1:-1].strip()
    return text


def operator_topology(expression: str) -> str:
    text = normalized_expression(expression)
    reserved = FUNCTIONS | GROUPS | BASE_VARS
    text = re.sub(
        r"\b[a-z_][a-z0-9_]*\b",
        lambda m: m.group(0) if m.group(0) in reserved else "field",
        text,
    )
    return text


def _behavior_topology(expression: str) -> str:
    text = _strip_outer(operator_topology(expression))
    # Whole-expression sign and scalar multiplication do not change behavior risk.
    for _ in range(4):
        changed = False
        if text.startswith("-(") and text.endswith(")"):
            text = _strip_outer(text[1:])
            changed = True
        elif text.startswith("-"):
            text = _strip_outer(text[1:])
            changed = True
        scalar = re.match(r"^-?#\*\((.*)\)$", text)
        if scalar:
            text = _strip_outer(scalar.group(1))
            changed = True
        scalar = re.match(r"^\((.*)\)\*-?#$", text)
        if scalar:
            text = _strip_outer(scalar.group(1))
            changed = True
        if not changed:
            break
    text = re.sub(r"(?<=\))[-+]#(?=[,)]|$)", "", text)
    text = re.sub(r"(?<=\w)[-+]#(?=[,)]|$)", "", text)
    # The numeric canonicalizer consumes the sign in ``-0.5``; a number
    # directly following a completed signal node is therefore a centering
    # constant rather than a function argument.
    text = re.sub(r"(?<=\))#(?=[,)]|$)", "", text)
    text = re.sub(r"\*-?#", "", text)
    text = text.replace("-rank(", "rank(").replace("+-", "+").replace("--", "")
    return _strip_outer(text)


def behavior_signature(
    expression: str, *, settings: dict[str, Any] | None = None
) -> str:
    del settings
    if not sig(expression):
        return ""
    fields = "|".join(sorted(extract_fields(expression))[:8]) or "-"
    return f"{fields}::{_behavior_topology(expression)}"


def structure_signature(expression: str) -> str:
    functions = ">".join(extract_functions(expression)[:12]) or "raw"
    fields = "|".join(sorted(extract_fields(expression))[:8]) or "-"
    return f"{functions}::{fields}::{operator_topology(expression)}"


# Legacy-compatible names.
_normalized_expression = normalized_expression
_structure_signature = structure_signature
_behavior_signature = behavior_signature
HYPOTHESIS
"""L2 structured hypothesis generation with embedding-based semantic deduplication."""

from __future__ import annotations

import json
import math
import sqlite3
import struct
import uuid
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import TYPE_CHECKING, Any, Mapping, Protocol, Sequence

if TYPE_CHECKING:
    from alpha_mining.filter.insights import RepairInsights


class TopicNotFoundError(LookupError):
    """The requested active research topic does not exist."""


class InvalidHypothesisOutput(ValueError):
    """The LLM response did not match the required structured contract."""


class DuplicateHypothesisError(RuntimeError):
    """Every bounded generation attempt was semantically duplicate."""


class EmbeddingDimensionError(ValueError):
    """Stored and generated embeddings use incompatible dimensions."""


class StructuredLLM(Protocol):
    def generate_json(
        self,
        *,
        system_prompt: str,
        user_prompt: str,
        json_schema: dict[str, Any],
    ) -> Mapping[str, Any]: ...


class EmbeddingClient(Protocol):
    def embed(self, text: str) -> Sequence[float]: ...


HYPOTHESIS_JSON_SCHEMA: dict[str, Any] = {
    "type": "object",
    "additionalProperties": False,
    "properties": {
        "hypothesis_statement": {"type": "string", "minLength": 1},
        "mechanism": {"type": "string", "minLength": 1},
        "horizon": {"type": "string", "enum": ["short", "medium", "long"]},
        "expected_direction": {"type": "string", "minLength": 1},
        "candidate_data_concepts": {
            "type": "array",
            "minItems": 1,
            "items": {"type": "string", "minLength": 1},
        },
    },
    "required": [
        "hypothesis_statement",
        "mechanism",
        "horizon",
        "expected_direction",
        "candidate_data_concepts",
    ],
}


@dataclass(frozen=True)
class HypothesisDraft:
    hypothesis_statement: str
    mechanism: str
    horizon: str
    expected_direction: str
    candidate_data_concepts: tuple[str, ...]


@dataclass(frozen=True)
class GeneratedHypothesis:
    hypothesis_id: str
    topic_id: str
    draft: HypothesisDraft
    embedding: tuple[float, ...]
    max_similarity: float


def encode_embedding(vector: Sequence[float]) -> bytes:
    values = tuple(float(value) for value in vector)
    if not values:
        raise ValueError("embedding must be non-empty")
    if any(not math.isfinite(value) for value in values):
        raise ValueError("embedding values must be finite")
    return struct.pack(f"<{len(values)}f", *values)


def decode_embedding(blob: bytes) -> tuple[float, ...]:
    if not blob or len(blob) % 4:
        raise ValueError("embedding BLOB length must be a non-zero multiple of 4")
    count = len(blob) // 4
    return tuple(struct.unpack(f"<{count}f", blob))


def _validated_draft(raw: Mapping[str, Any]) -> HypothesisDraft:
    expected = set(HYPOTHESIS_JSON_SCHEMA["required"])
    if set(raw) != expected:
        raise InvalidHypothesisOutput(
            "structured hypothesis fields do not match the JSON schema"
        )
    text_fields = (
        "hypothesis_statement",
        "mechanism",
        "horizon",
        "expected_direction",
    )
    cleaned: dict[str, str] = {}
    for field in text_fields:
        value = raw.get(field)
        if not isinstance(value, str) or not value.strip():
            raise InvalidHypothesisOutput(f"{field} must be a non-empty string")
        cleaned[field] = value.strip()
    if cleaned["horizon"] not in {"short", "medium", "long"}:
        raise InvalidHypothesisOutput("horizon must be short, medium, or long")
    concepts = raw.get("candidate_data_concepts")
    if not isinstance(concepts, list) or not concepts:
        raise InvalidHypothesisOutput(
            "candidate_data_concepts must be a non-empty list"
        )
    cleaned_concepts: list[str] = []
    for concept in concepts:
        if not isinstance(concept, str) or not concept.strip():
            raise InvalidHypothesisOutput(
                "candidate_data_concepts entries must be non-empty strings"
            )
        if concept.strip() not in cleaned_concepts:
            cleaned_concepts.append(concept.strip())
    return HypothesisDraft(
        hypothesis_statement=cleaned["hypothesis_statement"],
        mechanism=cleaned["mechanism"],
        horizon=cleaned["horizon"],
        expected_direction=cleaned["expected_direction"],
        candidate_data_concepts=tuple(cleaned_concepts),
    )


def _cosine_similarity(left: Sequence[float], right: Sequence[float]) -> float:
    if len(left) != len(right):
        raise EmbeddingDimensionError(
            f"embedding dimensions differ: generated={len(left)} stored={len(right)}"
        )
    left_norm = math.sqrt(sum(value * value for value in left))
    right_norm = math.sqrt(sum(value * value for value in right))
    if left_norm == 0 or right_norm == 0:
        raise EmbeddingDimensionError(
            "zero-length embedding vectors cannot be compared"
        )
    return sum(a * b for a, b in zip(left, right)) / (left_norm * right_norm)


class HypothesisGenerator:
    def __init__(
        self,
        database: str | Path,
        *,
        llm: StructuredLLM,
        embedder: EmbeddingClient,
        model_id: str,
        similarity_threshold: float = 0.90,
        max_attempts: int = 3,
        use_repair_insights: bool = False,
    ) -> None:
        if not 0.0 <= similarity_threshold <= 1.0:
            raise ValueError("similarity_threshold must be between 0 and 1")
        if max_attempts < 1:
            raise ValueError("max_attempts must be positive")
        if not model_id.strip():
            raise ValueError("model_id must not be empty")
        self.database = Path(database).expanduser().resolve()
        self.llm = llm
        self.embedder = embedder
        self.model_id = model_id.strip()
        self.similarity_threshold = float(similarity_threshold)
        self.max_attempts = int(max_attempts)
        self.use_repair_insights = bool(use_repair_insights)

    def _context(self, topic_id: str) -> tuple[str, list[str], list[tuple[float, ...]]]:
        with sqlite3.connect(self.database) as connection:
            topic = connection.execute(
                "SELECT description FROM research_topics WHERE topic_id=? AND active=1",
                (topic_id,),
            ).fetchone()
            if topic is None:
                raise TopicNotFoundError(f"active research topic not found: {topic_id}")
            statements = [
                str(row[0])
                for row in connection.execute(
                    "SELECT statement_cn FROM hypotheses WHERE topic_id=? ORDER BY created_at",
                    (topic_id,),
                )
            ]
            embeddings = [
                decode_embedding(bytes(row[0]))
                for row in connection.execute(
                    "SELECT embedding FROM hypotheses WHERE embedding IS NOT NULL"
                )
            ]
        return str(topic[0]), statements, embeddings

    @staticmethod
    def _prompt(
        topic_id: str,
        description: str,
        statements: Sequence[str],
        *,
        insights: RepairInsights | None = None,
    ) -> str:
        base = (
            f"Research topic id: {topic_id}\n"
            f"Topic description: {description}\n"
            "Existing hypotheses for this topic:\n"
            f"{json.dumps(list(statements), ensure_ascii=False)}\n"
            "Generate exactly one economically falsifiable hypothesis that is semantically different "
            "from every existing hypothesis. Return only data matching the supplied JSON schema."
        )
        if insights is not None:
            if insights.avoided_data_concepts:
                base += (
                    "\nConstraint: avoid proposing hypotheses that rely primarily on these data fields"
                    " (recent platform over-correlation failures indicate market saturation for them): "
                    + ", ".join(insights.avoided_data_concepts)
                    + "."
                )
            if insights.preferred_horizon:
                base += (
                    f"\nConstraint: prefer {insights.preferred_horizon} horizon hypotheses"
                    " (recent short-horizon alphas failed in-sample stability ladder checks;"
                    " longer horizons improve regime consistency)."
                )
        return base

    def generate(self, topic_id: str) -> GeneratedHypothesis:
        description, statements, historical_embeddings = self._context(topic_id)
        insights: RepairInsights | None = None
        if self.use_repair_insights:
            from alpha_mining.filter.insights import load_repair_insights

            insights = load_repair_insights(self.database)
        rejected_statements: list[str] = []
        last_invalid: InvalidHypothesisOutput | None = None
        duplicate_attempts = 0
        for attempt in range(1, self.max_attempts + 1):
            prompt_statements = [*statements, *rejected_statements]
            raw = self.llm.generate_json(
                system_prompt=(
                    "You are a quantitative research hypothesis generator. Produce structured, "
                    "testable claims; do not produce alpha expressions or free-form commentary."
                ),
                user_prompt=self._prompt(
                    topic_id, description, prompt_statements, insights=insights
                ),
                json_schema=HYPOTHESIS_JSON_SCHEMA,
            )
            try:
                draft = _validated_draft(raw)
            except InvalidHypothesisOutput as exc:
                last_invalid = exc
                if attempt == self.max_attempts:
                    raise
                continue
            embedding = tuple(
                float(value)
                for value in self.embedder.embed(draft.hypothesis_statement)
            )
            encode_embedding(embedding)
            similarities = [
                _cosine_similarity(embedding, historical)
                for historical in historical_embeddings
            ]
            max_similarity = max(similarities, default=0.0)
            if max_similarity >= self.similarity_threshold:
                duplicate_attempts += 1
                rejected_statements.append(draft.hypothesis_statement)
                continue

            hypothesis_id = f"hyp_{uuid.uuid4().hex}"
            created_at = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
            with sqlite3.connect(self.database) as connection:
                connection.execute("PRAGMA foreign_keys = ON")
                connection.execute(
                    """
                    INSERT INTO hypotheses (
                        hypothesis_id, topic_id, statement_cn, statement_en, mechanism,
                        horizon, embedding, created_at, llm_model, status
                    ) VALUES (?, ?, ?, NULL, ?, ?, ?, ?, ?, 'active')
                    """,
                    (
                        hypothesis_id,
                        topic_id,
                        draft.hypothesis_statement,
                        draft.mechanism,
                        draft.horizon,
                        encode_embedding(embedding),
                        created_at,
                        self.model_id,
                    ),
                )
            return GeneratedHypothesis(
                hypothesis_id=hypothesis_id,
                topic_id=topic_id,
                draft=draft,
                embedding=embedding,
                max_similarity=max_similarity,
            )
        if duplicate_attempts:
            raise DuplicateHypothesisError(
                f"all {self.max_attempts} attempts exceeded semantic similarity threshold "
                f"{self.similarity_threshold:.2f}"
            )
        if last_invalid is not None:
            raise last_invalid
        raise RuntimeError("hypothesis generation exhausted without a result")
SETTINGS_OPTIMIZER
"""Three-stage settings selection without Cartesian-product search."""

from __future__ import annotations

from dataclasses import dataclass
import hashlib
import json
import sqlite3
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


@dataclass(frozen=True)
class SettingTrial:
    profile: str
    settings: dict[str, Any]
    parameter_delta: dict[str, Any]
    purpose: str = "ROBUSTNESS_ONLY"


class SettingsOptimizer:
    def __init__(
        self,
        *,
        max_local_trials: int = 6,
        total_budget: int = 64,
        per_candidate_budget: int | None = None,
    ) -> None:
        self.max_local_trials = max(0, int(max_local_trials))
        self.total_budget = max(0, int(total_budget))
        self.per_candidate_budget = max(
            0,
            int(
                self.max_local_trials
                if per_candidate_budget is None
                else per_candidate_budget
            ),
        )
        self.consumed = 0
        self._candidate_reserved: dict[str, int] = {}

    def stage1_default(
        self, family: str, priors: list[dict] | None = None
    ) -> dict[str, Any]:
        defaults = {
            "region": "USA",
            "universe": "TOP3000",
            "delay": 1,
            "neutralization": "SUBINDUSTRY",
            "decay": 0,
            "truncation": 0.08,
            "nanHandling": "ON",
            "pasteurization": "ON",
        }
        viable = sorted(
            priors or [],
            key=lambda item: (
                float(item.get("smoothed_success", 0)),
                -float(item.get("simulation_cost", 0)),
            ),
            reverse=True,
        )
        return {**defaults, **(viable[0].get("settings", {}) if viable else {})}

    def local_trials(
        self,
        base: dict[str, Any],
        *,
        quality_score: float,
        metric_ratio: float,
        delay_allowed: bool = False,
        candidate_id: str = "__single_candidate__",
        candidate_classification: str = "RECHECK",
    ) -> list[SettingTrial]:
        if str(candidate_classification).upper() == "ARCHIVE":
            return []
        # Only near-pass candidates or candidates with an explicit high-potential
        # score receive local search budget.
        if quality_score < 0.7 and metric_ratio < 0.90:
            return []
        candidates = [
            (
                "neutralization",
                "INDUSTRY"
                if base.get("neutralization") != "INDUSTRY"
                else "SUBINDUSTRY",
            ),
            ("decay", 2 if int(base.get("decay", 0)) != 2 else 4),
            (
                "truncation",
                0.06 if float(base.get("truncation", 0.08)) != 0.06 else 0.10,
            ),
            ("nanHandling", "OFF" if base.get("nanHandling") == "ON" else "ON"),
            (
                "pasteurization",
                "OFF" if base.get("pasteurization", "ON") == "ON" else "ON",
            ),
        ]
        if delay_allowed:
            candidates.append(("delay", 0 if int(base.get("delay", 1)) == 1 else 1))
        out = []
        available = max(0, self.total_budget - self.consumed)
        candidate_key = str(candidate_id or "__missing_candidate__")
        candidate_available = max(
            0,
            self.per_candidate_budget - self._candidate_reserved.get(candidate_key, 0),
        )
        limit = min(self.max_local_trials, available, candidate_available)
        for key, value in candidates[:limit]:
            settings = dict(base)
            settings[key] = value
            purpose = (
                "STABILITY_TURNOVER_ONLY"
                if key in {"decay", "truncation"}
                else "ROBUSTNESS_ONLY"
            )
            out.append(SettingTrial(f"ofat_{key}", settings, {key: value}, purpose))
        reserved = len(out)
        self._candidate_reserved[candidate_key] = (
            self._candidate_reserved.get(candidate_key, 0) + reserved
        )
        self.consumed = min(self.total_budget, self.consumed + reserved)
        return out

    def consume(self, count: int = 1) -> None:
        self.consumed = min(self.total_budget, self.consumed + max(0, int(count)))

    def budget_status(self) -> str:
        return "BUDGET_EXHAUSTED" if self.consumed >= self.total_budget else "AVAILABLE"

    def candidate_budget_status(self, candidate_id: str) -> str:
        used = self._candidate_reserved.get(str(candidate_id), 0)
        if used == 0:
            return "UNUSED"
        return "BUDGET_EXHAUSTED" if used >= self.per_candidate_budget else "AVAILABLE"

    def persist_result(
        self,
        database: str | Path,
        *,
        expression_id: str,
        trial: SettingTrial,
        metrics: dict,
        checks: list[dict],
        quality_score: float,
        robustness_score: float,
        simulation_cost: float,
    ) -> str:
        created_at = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
        trial_id = hashlib.sha256(
            f"{expression_id}\0{trial.profile}\0{json.dumps(trial.settings, sort_keys=True)}\0{created_at}".encode()
        ).hexdigest()
        with sqlite3.connect(database) as con:
            con.execute(
                """INSERT INTO settings_trials(trial_id,expression_id,setting_profile,parameter_delta_json,metrics_json,checks_json,quality_score,robustness_score,simulation_cost,created_at)
                VALUES (?,?,?,?,?,?,?,?,?,?)""",
                (
                    trial_id,
                    expression_id,
                    trial.profile,
                    json.dumps(trial.parameter_delta, sort_keys=True),
                    json.dumps(metrics, sort_keys=True),
                    json.dumps(checks, sort_keys=True),
                    quality_score,
                    robustness_score,
                    simulation_cost,
                    created_at,
                ),
            )
        return trial_id
BANDIT
"""Persistent bounded-arm reward accounting for consultant exploration."""

from __future__ import annotations

import hashlib
import json
import sqlite3
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path

from alpha_mining.policy.consultant_policy import ConsultantPolicy


@dataclass(frozen=True)
class BanditArm:
    family: str
    dataset: str
    mutation_type: str
    settings_profile: str

    @property
    def key(self) -> str:
        return "|".join(
            (self.family, self.dataset, self.mutation_type, self.settings_profile)
        )


class ConsultantBandit:
    def __init__(
        self, database: str | Path, *, policy: ConsultantPolicy | None = None
    ) -> None:
        self.database = Path(database)
        self.policy = policy or ConsultantPolicy()

    def reward(self, arm: BanditArm, components: dict[str, float | bool]) -> float:
        value = sum(
            self.policy.reward_weights.get(name, 0.0) * float(component)
            for name, component in components.items()
        )
        now = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
        event_id = hashlib.sha256(
            f"{arm.key}\0{now}\0{json.dumps(components, sort_keys=True)}".encode()
        ).hexdigest()
        with sqlite3.connect(self.database) as con:
            con.execute(
                "INSERT INTO consultant_bandit_events(event_id,arm_key,reward,components_json,created_at) VALUES (?,?,?,?,?)",
                (event_id, arm.key, value, json.dumps(components, sort_keys=True), now),
            )
        return value

    def scores(self) -> dict[str, float]:
        with sqlite3.connect(self.database) as con:
            return {
                key: float(value)
                for key, value in con.execute(
                    "SELECT arm_key,AVG(reward) FROM consultant_bandit_events GROUP BY arm_key"
                )
            }
CLUSTER_FREEZE
"""Cluster-level Prod Corr crowding statistics and freeze policy.

A frozen cluster means: enough platform observations exist, every one failed
PROD_CORRELATION, and the median observed value is clearly above the live cutoff.
Frozen clusters must not spawn further parameter/settings variants — only
mechanism-level rewrites are permitted.

Usage::

    registry = ClusterFreezeRegistry(db_path="research_memory.sqlite")
    registry.refresh()

    if registry.is_frozen("my_sig::rank_ts_delta"):
        # skip this parent's offspring generation
        ...
"""

from __future__ import annotations

import sqlite3
import statistics
from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True)
class ClusterCrowdingStats:
    cluster_id: str           # behavior_signature used as cluster key
    observation_count: int
    pass_count: int
    fail_count: int
    pass_rate: float          # 0.0–1.0
    median_prod_corr: float | None
    live_cutoff: float | None
    should_freeze: bool

    @property
    def margin_above_cutoff(self) -> float | None:
        """How far the median sits above the live cutoff (positive = bad)."""
        if self.median_prod_corr is None or self.live_cutoff is None:
            return None
        return self.median_prod_corr - self.live_cutoff


class ClusterFreezeRegistry:
    """Computes and caches freeze decisions for behavior-signature clusters.

    Freeze condition (all must hold):
    - observation_count >= min_observations
    - pass_count == 0
    - median_prod_corr > live_cutoff + freeze_margin
    - freeze_margin and min_observations are configurable; no hard-coded 0.7/0.8.

    The live cutoff is read from platform_gate_snapshots (gate_name=PROD_CORRELATION).
    If no snapshot exists, the registry falls back to fallback_cutoff (default 0.7)
    but marks the decision as uncertain.
    """

    def __init__(
        self,
        db_path: str | Path,
        *,
        min_observations: int = 5,
        freeze_margin: float = 0.05,
        fallback_cutoff: float = 0.70,
    ) -> None:
        self.db_path = Path(db_path)
        self.min_observations = min_observations
        self.freeze_margin = freeze_margin
        self.fallback_cutoff = fallback_cutoff
        self._frozen: set[str] = set()
        self._stats: dict[str, ClusterCrowdingStats] = {}

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def refresh(self) -> None:
        """Recompute freeze decisions from the database. Call before each cycle."""
        if not self.db_path.exists():
            return
        with sqlite3.connect(self.db_path) as con:
            live_cutoff = self._load_live_cutoff(con)
            rows = self._load_cluster_observations(con)

        self._frozen.clear()
        self._stats.clear()

        # Group by behavior_cluster_id (falls back to expression_id if cluster unknown).
        from collections import defaultdict
        groups: dict[str, list[dict]] = defaultdict(list)
        for row in rows:
            key = str(row["cluster_id"] or row["expression_id"] or "")
            if key:
                groups[key].append(row)

        effective_cutoff = live_cutoff if live_cutoff is not None else self.fallback_cutoff

        for cluster_id, obs in groups.items():
            n = len(obs)
            pass_count = sum(1 for o in obs if str(o["status"]).upper() == "PASS")
            fail_count = sum(1 for o in obs if str(o["status"]).upper() == "FAIL")
            corr_values = [
                o["prod_correlation"]
                for o in obs
                if o["prod_correlation"] is not None
            ]
            median_corr = statistics.median(corr_values) if corr_values else None

            should_freeze = (
                n >= self.min_observations
                and pass_count == 0
                and median_corr is not None
                and median_corr > effective_cutoff + self.freeze_margin
            )

            stats = ClusterCrowdingStats(
                cluster_id=cluster_id,
                observation_count=n,
                pass_count=pass_count,
                fail_count=fail_count,
                pass_rate=pass_count / n if n > 0 else 0.0,
                median_prod_corr=median_corr,
                live_cutoff=effective_cutoff,
                should_freeze=should_freeze,
            )
            self._stats[cluster_id] = stats
            if should_freeze:
                self._frozen.add(cluster_id)

    def is_frozen(self, cluster_id_or_signature: str) -> bool:
        """Return True if this cluster should not generate more offspring."""
        return cluster_id_or_signature in self._frozen

    def all_stats(self) -> list[ClusterCrowdingStats]:
        return list(self._stats.values())

    def frozen_clusters(self) -> list[str]:
        return sorted(self._frozen)

    # ------------------------------------------------------------------
    # Private helpers
    # ------------------------------------------------------------------

    def _load_live_cutoff(self, con: sqlite3.Connection) -> float | None:
        """Read the most recent PROD_CORRELATION gate snapshot limit."""
        row = con.execute(
            "SELECT limit_value FROM platform_gate_snapshots "
            "WHERE gate_name = 'PROD_CORRELATION' "
            "ORDER BY last_seen_at DESC LIMIT 1"
        ).fetchone()
        if row and row[0] is not None:
            try:
                return float(row[0])
            except (TypeError, ValueError):
                pass
        return None

    def _load_cluster_observations(self, con: sqlite3.Connection) -> list[dict]:
        """Load all prod_corr observations joined with cluster info."""
        # Check if the prod_correlation_observations table exists (migration v4).
        tables = {
            r[0]
            for r in con.execute(
                "SELECT name FROM sqlite_master WHERE type='table'"
            )
        }
        if "prod_correlation_observations" not in tables:
            return []

        rows = con.execute(
            "SELECT alpha_id, expression_id, behavior_cluster_id, "
            "       prod_correlation, status "
            "FROM prod_correlation_observations"
        ).fetchall()

        return [
            {
                "alpha_id": r[0],
                "expression_id": r[1],
                "cluster_id": r[2],  # may be None
                "prod_correlation": r[3],
                "status": r[4],
            }
            for r in rows
        ]

